/**
 * Example usage of acme-retry package
 * Demonstrates retrying a flaky function 5 times with exponential backoff
 */

const { retry } = require('acme-retry');

// A simulated flaky function that fails 3 times before succeeding
let attemptCount = 0;
async function flakyFunction() {
  attemptCount++;
  console.log(`Attempt ${attemptCount}...`);

  // Simulate random failures
  if (attemptCount < 4) {
    throw new Error(`Failed on attempt ${attemptCount}`);
  }

  return `Success on attempt ${attemptCount}!`;
}

// Another example: a function that might fail due to network issues
async function fetchDataSimulation() {
  const random = Math.random();
  console.log(`Fetch attempt (random value: ${random.toFixed(2)})`);

  if (random < 0.7) {
    throw new Error('Network timeout or server error');
  }

  return { data: 'Sample data', status: 'ok' };
}

// Main example
async function main() {
  console.log('=== Example 1: Retrying a flaky function ===');
  console.log('This function will fail 3 times then succeed on the 4th attempt:');

  try {
    // Reset attempt count
    attemptCount = 0;

    // Retry up to 5 times with exponential backoff starting at 100ms
    const result = await retry(flakyFunction, { 
      attempts: 5, 
      baseMs: 100 
    });

    console.log(`Result: ${result}`);
  } catch (error) {
    console.error(`All retries failed: ${error.message}`);
  }

  console.log('\n=== Example 2: Simulating API calls with retry ===');
  console.log('Simulating network requests with 70% failure rate:');

  try {
    const data = await retry(fetchDataSimulation, {
      attempts: 5,
      baseMs: 200  // Start with 200ms, then 400ms, 800ms, etc.
    });

    console.log(`Data retrieved successfully:`, data);
  } catch (error) {
    console.error(`Failed to fetch data after all retries: ${error.message}`);
  }

  console.log('\n=== Example 3: Custom error handling ===');

  // Function that checks for specific error types
  async function validateUser(userId) {
    console.log(`Validating user ${userId}...`);

    // Simulate validation that fails with specific errors
    const random = Math.random();
    if (random < 0.3) {
      throw new Error('Database connection error');
    } else if (random < 0.6) {
      throw new Error('Invalid user data format');
    } else if (random < 0.8) {
      // This error type might be retryable
      throw new Error('Temporary service unavailability');
    }

    return { userId, valid: true, timestamp: new Date().toISOString() };
  }

  try {
    const validation = await retry(() => validateUser('user123'), {
      attempts: 4,
      baseMs: 150
    });

    console.log('Validation successful:', validation);
  } catch (error) {
    console.error(`Validation failed: ${error.message}`);

    // You could examine error type here to decide what to do next
    if (error.message.includes('Invalid user data')) {
      console.log('This is a data error, not retryable');
    }
  }
}

// Run the examples
main().catch(console.error);

