/**
 * Example usage of acme-retry package
 * 
 * This demonstrates how to use the retry function with exponential backoff
 * to handle flaky operations that might fail intermittently.
 */

const { retry } = require('acme-retry');

/**
 * A flaky function that simulates an unreliable operation
 * It will fail 4 times before succeeding on the 5th attempt
 */
let callCount = 0;
async function flakyAPICall() {
  callCount++;
  console.log(`Attempt ${callCount}: Calling flaky API...`);

  // Simulate a flaky operation that fails 4 times then succeeds
  if (callCount < 5) {
    // Simulate different types of failures
    const errors = [
      new Error('Network timeout'),
      new Error('Server 502 Bad Gateway'),
      new Error('Database connection lost'),
      new Error('Rate limit exceeded')
    ];
    throw errors[callCount - 1];
  }

  console.log(`Success on attempt ${callCount}!`);
  return {
    data: 'API call successful',
    timestamp: new Date().toISOString(),
    attempt: callCount
  };
}

/**
 * Another example: A function that randomly fails
 */
async function unreliableDatabaseQuery() {
  console.log('Running database query...');

  // 30% chance of failure
  if (Math.random() < 0.3) {
    throw new Error('Database query failed: deadlock detected');
  }

  return { result: 'Query successful', rows: 42 };
}

/**
 * Main demonstration
 */
async function demonstrateRetry() {
  console.log('=== Example 1: Retrying a flaky API call ===\n');

  // Reset counter for the first example
  callCount = 0;

  try {
    // Use retry with 5 attempts and 200ms base delay
    const result = await retry(flakyAPICall, {
      attempts: 5,
      baseMs: 200
    });

    console.log('\n✅ Final result:', result);
    console.log(`Total attempts made: ${callCount}`);

  } catch (error) {
    console.error('\n❌ All attempts failed:', error.message);
  }

  console.log('\n' + '='.repeat(50) + '\n');
  console.log('=== Example 2: Retrying an unreliable database query ===\n');

  try {
    // Reset counter and use different configuration
    callCount = 0;
    const queryResult = await retry(async () => {
      callCount++;
      console.log(`Database attempt ${callCount}...`);

      // 40% chance of failure for this example
      if (Math.random() < 0.4) {
        throw new Error(`Query failed on attempt ${callCount}`);
      }

      console.log(`Database query succeeded on attempt ${callCount}`);
      return { data: `Result from attempt ${callCount}`, value: Math.random() };
    }, {
      attempts: 4,
      baseMs: 100  // Shorter base delay
    });

    console.log('\n✅ Database query result:', queryResult);

  } catch (error) {
    console.error('\n❌ Database query failed after all attempts:', error.message);
  }

  console.log('\n' + '='.repeat(50) + '\n');
  console.log('=== Example 3: Using default settings ===\n');

  try {
    callCount = 0;
    // Using retry with default settings (3 attempts, 100ms base delay)
    const defaultResult = await retry(async () => {
      callCount++;
      console.log(`Default attempt ${callCount}...`);

      if (callCount < 3) {
        throw new Error(`Failing on attempt ${callCount}`);
      }

      return `Succeeded on attempt ${callCount}`;
    });

    console.log('\n✅ Default retry result:', defaultResult);

  } catch (error) {
    console.error('\n❌ Default retry failed:', error.message);
  }
}

/**
 * How acme-retry works:
 * 
 * 1. Exponential Backoff: The delay between retries increases exponentially:
 *    - 1st retry: baseMs * 2^0 = baseMs
 *    - 2nd retry: baseMs * 2^1 = baseMs * 2  
 *    - 3rd retry: baseMs * 2^2 = baseMs * 4
 *    - etc.
 * 
 * 2. Attempts: You specify the maximum number of attempts (including the first try)
 * 
 * 3. Error Propagation: If all attempts fail, the last error is thrown
 * 
 * 4. Simplicity: The function returns a promise that resolves when the operation
 *    succeeds or rejects after all attempts fail
 */

// Run the demonstration
if (require.main === module) {
  demonstrateRetry().catch(console.error);
}

module.exports = { retry, flakyAPICall };

// Additional notes:
console.log('\n\n=== How acme-retry works ===');
console.log(`
The acme-retry package provides a simple exponential backoff retry mechanism:

1. Function Signature: retry(fn, opts)
   - fn: Async function to retry
   - opts: { attempts: number, baseMs: number }

2. Exponential Backoff Formula:
   Delay = baseMs * (2 ^ attemptNumber)
   Where attemptNumber starts at 0 for the first retry

3. Example with attempts=5, baseMs=100:
   - Try 1: Immediate (no delay)
   - Try 2: 100ms delay (100 * 2^0)
   - Try 3: 200ms delay (100 * 2^1)  
   - Try 4: 400ms delay (100 * 2^2)
   - Try 5: 800ms delay (100 * 2^3)

4. Use cases:
   - Flaky network requests
   - Unreliable external APIs
   - Intermittent database connections
   - Rate-limited operations

5. Best practices:
   - Use for transient failures (network, timeouts)
   - Don't use for permanent errors (validation, auth)
   - Set reasonable attempts to avoid long wait times
   - Consider circuit breaker patterns for production
`);

/**
 * Simple example using acme-retry to retry a flaky function 5 times
 */

const { retry } = require('acme-retry');

// A flaky function that fails 4 times before succeeding on the 5th attempt
let attemptCount = 0;
async function flakyFunction() {
  attemptCount++;
  console.log(`Attempt ${attemptCount}...`);

  // Simulate failure for first 4 attempts
  if (attemptCount < 5) {
    throw new Error(`Failed on attempt ${attemptCount}`);
  }

  return `Success on attempt ${attemptCount}!`;
}

// Main execution
async function main() {
  console.log('Testing acme-retry with a flaky function:\n');

  try {
    // Retry the flaky function up to 5 times with 100ms base delay
    const result = await retry(flakyFunction, {
      attempts: 5,
      baseMs: 100
    });

    console.log(`\n✅ Result: ${result}`);

  } catch (error) {
    console.error(`\n❌ All 5 attempts failed: ${error.message}`);
  }

  console.log('\n' + '='.repeat(50));
  console.log('\nHow acme-retry works:');
  console.log(`
1. The retry() function takes two parameters:
   - An async function to execute
   - Options: { attempts: number, baseMs: number }

2. With attempts=5 and baseMs=100, the retry pattern is:
   - Attempt 1: Immediate execution
   - Attempt 2: Wait 100ms (100 * 2^0 = 100)
   - Attempt 3: Wait 200ms (100 * 2^1 = 200)
   - Attempt 4: Wait 400ms (100 * 2^2 = 400)
   - Attempt 5: Wait 800ms (100 * 2^3 = 800)

3. This exponential backoff helps by:
   - Giving transient issues time to resolve
   - Preventing overwhelming the target system
   - Being more efficient than constant retry intervals

4. If the function succeeds on any attempt, retry() returns the result.
   If all attempts fail, it throws the last error encountered.
`);
}

// Run the example
main().catch(console.error);

// Quick test to verify acme-retry functionality
const { retry } = require('acme-retry');

async function testRetry() {
  console.log('Testing basic functionality...');

  // Test 1: Successful on first try
  console.log('\nTest 1: Success on first try');
  const result1 = await retry(() => Promise.resolve('immediate success'));
  console.log('✓', result1);

  // Test 2: Fail all attempts
  console.log('\nTest 2: Fail all 3 attempts (default)');
  let count2 = 0;
  try {
    await retry(() => {
      count2++;
      throw new Error(`Always failing: ${count2}`);
    });
  } catch (e) {
    console.log('✓ Caught error after 3 attempts:', e.message);
  }

  // Test 3: Custom attempts and baseMs
  console.log('\nTest 3: Custom options - 4 attempts, 50ms base');
  let count3 = 0;
  const startTime = Date.now();
  try {
    await retry(async () => {
      count3++;
      console.log(`  Attempt ${count3} at ${Date.now() - startTime}ms`);
      throw new Error('Still failing');
    }, { attempts: 4, baseMs: 50 });
  } catch (e) {
    console.log(`✓ Failed after ${count3} attempts with exponential delays`);
  }

  console.log('\nAll tests completed!');
}

testRetry().catch(console.error);

